create extension if not exists "pgcrypto";
create type vehicle_status as enum ('available','reserved','sold');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, role text not null default 'admin' check (role in ('admin')), created_at timestamptz not null default now());
create table public.vehicles (id uuid primary key default gen_random_uuid(),slug text unique not null,brand text not null,model text not null,version text,year integer not null,model_year integer not null,mileage integer,price numeric not null,color text,fuel text,transmission text,doors integer,plate_end text,description text,features text[] default '{}',status vehicle_status not null default 'available',featured boolean not null default false,show_when_sold boolean not null default false,cover_image text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.vehicle_images (id uuid primary key default gen_random_uuid(),vehicle_id uuid not null references public.vehicles(id) on delete cascade,url text not null,position integer not null default 0,created_at timestamptz not null default now());
create table public.leads (id uuid primary key default gen_random_uuid(),name text not null,phone text not null,type text not null,vehicle_id uuid references public.vehicles(id) on delete set null,message text,created_at timestamptz not null default now());
create table public.site_settings (id uuid primary key default gen_random_uuid(),key text unique not null,value jsonb not null,updated_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin')$$;
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
create trigger vehicles_updated_at before update on public.vehicles for each row execute procedure public.touch_updated_at();
alter table public.profiles enable row level security;alter table public.vehicles enable row level security;alter table public.vehicle_images enable row level security;alter table public.leads enable row level security;alter table public.site_settings enable row level security;
create policy "public reads published vehicles" on public.vehicles for select using (status='available' or (status='sold' and show_when_sold));
create policy "admins manage vehicles" on public.vehicles for all using (public.is_admin()) with check (public.is_admin());
create policy "public reads vehicle images" on public.vehicle_images for select using (exists(select 1 from public.vehicles v where v.id=vehicle_id and (v.status='available' or (v.status='sold' and v.show_when_sold))));
create policy "admins manage images" on public.vehicle_images for all using (public.is_admin()) with check (public.is_admin());
create policy "admins read leads" on public.leads for select using (public.is_admin());create policy "admins manage settings" on public.site_settings for all using (public.is_admin()) with check (public.is_admin());create policy "admins read profiles" on public.profiles for select using (id=auth.uid());
insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('vehicle-images','vehicle-images',true,10485760,array['image/jpeg','image/png','image/webp']) on conflict (id) do nothing;
create policy "public reads vehicle storage" on storage.objects for select using (bucket_id='vehicle-images');create policy "admins manage vehicle storage" on storage.objects for all using (bucket_id='vehicle-images' and public.is_admin()) with check (bucket_id='vehicle-images' and public.is_admin());
